package com.orderflow.notification;import java.time.Clock;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.boot.context.properties.ConfigurationPropertiesScan;import org.springframework.context.annotation.Bean;import org.springframework.scheduling.annotation.*;
@SpringBootApplication @ConfigurationPropertiesScan @EnableScheduling @EnableAsync public class NotificationServiceApplication{public static void main(String[]a){SpringApplication.run(NotificationServiceApplication.class,a);}@Bean Clock notificationClock(){return Clock.systemUTC();}}
